WITH inner_cte AS ( SELECT ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC, VARIANCE(TIP_DETAIL.RECORD_COUNT) AS record_count_variance FROM TIP_DETAIL JOIN ACADEMIC_TERMS_ALL ON TIP_DETAIL.TERM_CODE = ACADEMIC_TERMS_ALL.TERM_CODE JOIN ACADEMIC_TERM_PARAMETER ON ACADEMIC_TERMS_ALL.TERM_CODE = ACADEMIC_TERM_PARAMETER.TERM_CODE WHERE ACADEMIC_TERM_PARAMETER.TERM_PARAMETER IN ('SIS_CURRENT_TERM', 'SIS_PREVIOUS_TERM') GROUP BY ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC ORDER BY record_count_variance DESC ), geometric_mean_record_count_cte AS ( SELECT ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC, EXP(AVG(LN(TIP_DETAIL.RECORD_COUNT))) AS geometric_mean_record_count FROM COURSE_CATALOG_SUBJECT_OFFERED JOIN ACADEMIC_TERMS_ALL ON COURSE_CATALOG_SUBJECT_OFFERED.TERM_CODE = ACADEMIC_TERMS_ALL.TERM_CODE JOIN TIP_DETAIL ON ACADEMIC_TERMS_ALL.TERM_CODE = TIP_DETAIL.TERM_CODE WHERE TIP_DETAIL.RECORD_COUNT > 0 AND TIP_DETAIL.TIP_MATERIAL_STATUS_KEY = 'RQ' GROUP BY ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC ORDER BY geometric_mean_record_count DESC ), department_count_cte AS ( SELECT ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC, COUNT(DISTINCT COURSE_CATALOG_SUBJECT_OFFERED.DEPARTMENT_CODE) AS unique_department_count FROM COURSE_CATALOG_SUBJECT_OFFERED JOIN ACADEMIC_TERMS_ALL ON COURSE_CATALOG_SUBJECT_OFFERED.TERM_CODE = ACADEMIC_TERMS_ALL.TERM_CODE GROUP BY ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC ) SELECT inner_cte.ACADEMIC_YEAR, inner_cte.ACADEMIC_YEAR_DESC, inner_cte.record_count_variance, geometric_mean_record_count_cte.geometric_mean_record_count, department_count_cte.unique_department_count FROM inner_cte JOIN geometric_mean_record_count_cte ON inner_cte.ACADEMIC_YEAR = geometric_mean_record_count_cte.ACADEMIC_YEAR AND inner_cte.ACADEMIC_YEAR_DESC = geometric_mean_record_count_cte.ACADEMIC_YEAR_DESC JOIN department_count_cte ON inner_cte.ACADEMIC_YEAR = department_count_cte.ACADEMIC_YEAR AND inner_cte.ACADEMIC_YEAR_DESC = department_count_cte.ACADEMIC_YEAR_DESC ORDER BY inner_cte.record_count_variance DESC;